#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    void (*execute)(void*);
    void (*undo)(void*);
    void *state;
} Command;

typedef struct { int a, b, result; } AddState;

void add_execute(void *s) {
    AddState *st = (AddState*)s;
    st->result = st->a + st->b;
    printf("Add: %d + %d = %d\n", st->a, st->b, st->result);
}

void add_undo(void *s) {
    AddState *st = (AddState*)s;
    printf("Undo add: %d\n", st->result);
}

int main() {
    AddState *as = malloc(sizeof(AddState));
    as->a = 10; as->b = 20;
    Command cmd = {add_execute, add_undo, as};
    cmd.execute(cmd.state);
    cmd.undo(cmd.state);
    free(as);
    return 0;
}
